 "Drawing Down the Malevolent", ["quest:96025"] = "As the Crow Flies", ["quest:96252"] = "Tarnished Treasures", ["quest:96296"] = "Fetid Corruption", ["quest:96959"] = "Blademaster's Bonfires", ["quest:96971"] = "To Outfox a Demon", ["quest:97009"] = "Maerion's Misery", ["zone:1452"] = "Winterspring", ["zone:2482"] = "Mount Hyjal" },
			written = { ["Experimental route (alpha): if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nEast from the Cradle towards the {area:16867}, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for {npc:260825}."] = "Experimental route (alpha): if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nEast from the Cradle towards the Shrine of Aviana, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for Phoebe.", ["Fly down to Bluebell for {npc:249235} and {npc:256222}."] = "Fly down to Bluebell for Kaylaena and Ketharas.", ["Into the burrow for the elders, {npc:260661} and {npc:256660}."] = "Into the burrow for the elders, Suma and Thobon.", ["North-east across the Cradle to {npc:249234}'s camp at the edge of {area:16866}."] = "North-east across the Cradle to Johun's camp at the edge of Dae'gun.", ["North-east to {npc:263394}: use {npc:263406}'s eye on him to drain him, then kill him. {npc:267439}, an elite (level 61), walks this corner of {area:16866}: keep out of his way.\n{npc:267097} waits a little further north-east. His Felhound Spikes come from the Defiling Hounds, and in our only recording about one hound in ten had one: kill the hounds around him while you are here, and leave his quest if the twelve spikes are slow to come."] = "North-east to Bethra'zel: use Elaena's eye on him to drain him, then kill him. Doomguard Xarkul, an elite (level 61), walks this corner of Dae'gun: keep out of his way.\nMaerion Thaelemaches waits a little further north-east. His Felhound Spikes come from the Defiling Hounds, and in our only recording about one hound in ten had one: kill the hounds around him while you are here, and leave his quest if the twelve spikes are slow to come.", ["The Blackthorne cultists camp on the slopes north-east of the Summit (level 60, with elite Outrunners, Priests and a Courier among them: pull carefully). {npc:260674}, an elite (level 60) who leads them, stands among them: leave him be. Ghansurok, an elite chimaera (level 61), also roams the ridge north of the camps.\nUse {npc:40833}'s staff on a Pact member to strip its ward, then kill it, ten times: pick Cultists and Adepts, whom Thisalee wants dead too. The Cultists carry the kris and the Adepts the staff; the thorn seeds lie in the woods there, and the hippogryphs and chimaeras roam the slopes all around. Not finished in our recordings yet: if something here is off, tell us."] = "The Blackthorne cultists camp on the slopes north-east of the Summit (level 60, with elite Outrunners, Priests and a Courier among them: pull carefully). Ve'han Talongrasp, an elite (level 60) who leads them, stands among them: leave him be. Ghansurok, an elite chimaera (level 61), also roams the ridge north of the camps.\nUse Tiala's staff on a Pact member to strip its ward, then kill it, ten times: pick Cultists and Adepts, whom Thisalee wants dead too. The Cultists carry the kris and the Adepts the staff; the thorn seeds lie in the woods there, and the hippogryphs and chimaeras roam the slopes all around. Not finished in our recordings yet: if something here is off, tell us.", ["The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and {npc:256660}'s amulets; the bangles lie in their nests, the {object:650219} in a nest on the western slope, and {npc:260826}, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine."] = "The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and Thobon's amulets; the bangles lie in their nests, the Jewel of the Horizon in a nest on the western slope, and Zarrat Wormwing, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine.", ["{npc:249235}'s workshop"] = "Kaylaena's workshop", ["{npc:252457}"] = "Mazzogore", ["{npc:263394} and {npc:267097}"] = "Bethra'zel and Maerion", ["{npc:263406}, {npc:249052} and {npc:267121}"] = "Elaena, Witherbeard and Yashiro" },
			steps = {
				{
					title = "Back to {zone:2482}",
					note = "Experimental route (alpha). It is written from Forever's quest data and the first recording of the zone, and some steps are not checked in game yet: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThis part carries on from part 2 in the {area:17145}: fly to the {area:16853} and ride north-west, or ride in from {area:2255} through {area:2256}.",
					when = { { k = "zone", neg = true, name = "Mount Hyjal", area = 616 } },
