			written = { ["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. Ghostmaw, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for Benjy (they drop Halligan's heads) and the Jumbo Crawfish in the shallows for the shells. Curly, one of Halligan's lumberjacks, is stuck on the bank just north-west of the murlocs; Robbie's hat lies on the riverbank among them; the fresh manure is in the fields of Meadowsbrook, between the river and the farm. Ghostmaw, an elite (level 42), prowls the river: if he comes your way, back off and let him pass.", ["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "East along the road towards Farholde Keep: hand Benjy his murlocs as you pass Wheeler's Grange.", ["North-east across the fields to {area:16725}: {npc:258317} wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads {npc:256438} needs, so one pass along the river does both."] = "North-east across the fields to Wheeler's Grange: Benjy Wheeler wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads Halligan needs, so one pass along the river does both.", ["Use {npc:256438}'s {item:266161} on bare ground around the camp: five saplings."] = "Use Halligan's Tree Sprouting Kit on bare ground around the camp: five saplings." },
